/* ============================================
   LearnForge Design System
   ============================================ */

/* CSS Custom Properties */
:root {
  /* Brand Colors - OKLCH */
  --brand-primary: oklch(55% 0.22 265);
  --brand-primary-light: oklch(65% 0.18 265);
  --brand-primary-dark: oklch(45% 0.24 265);
  --brand-accent: oklch(70% 0.18 145);
  --brand-accent-warm: oklch(75% 0.16 55);
  --brand-burgundy: oklch(35% 0.12 25);
  --brand-lime: oklch(85% 0.22 115);

  /* Neutral Scale */
  --text-primary: oklch(18% 0.02 265);
  --text-secondary: oklch(45% 0.03 265);
  --text-muted: oklch(60% 0.02 265);
  --bg-white: oklch(99% 0.005 265);
  --bg-surface: oklch(97% 0.01 265);
  --bg-elevated: oklch(100% 0 0);
  --border-light: oklch(88% 0.02 265);
  --border-medium: oklch(75% 0.03 265);

  /* Spacing Scale */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;
  --space-32: 8rem;

  /* Typography */
  --font-heading: 'Plus Jakarta Sans', 'Inter', system-ui, -apple-system, sans-serif;
  --font-body: 'Inter', system-ui, -apple-system, sans-serif;
  --text-xs: 0.75rem;
  --text-sm: 0.875rem;
  --text-base: 1rem;
  --text-lg: 1.125rem;
  --text-xl: 1.25rem;
  --text-2xl: 1.5rem;
  --text-3xl: 1.875rem;
  --text-4xl: 2.25rem;
  --text-5xl: 3rem;
  --text-6xl: 3.75rem;
  --text-7xl: 4.5rem;

  /* Border Radius */
  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-2xl: 1.5rem;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 2px 0 oklch(0% 0 0 / 0.05);
  --shadow-md: 0 4px 6px -1px oklch(0% 0 0 / 0.1), 0 2px 4px -2px oklch(0% 0 0 / 0.1);
  --shadow-lg: 0 10px 15px -3px oklch(0% 0 0 / 0.1), 0 4px 6px -4px oklch(0% 0 0 / 0.1);
  --shadow-xl: 0 20px 25px -5px oklch(0% 0 0 / 0.1), 0 8px 10px -6px oklch(0% 0 0 / 0.1);
  --shadow-card: 0 4px 20px -4px oklch(0% 0 0 / 0.08);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 350ms ease;

  /* Layout */
  --container-max: 1280px;
  --container-narrow: 1024px;
  --nav-height: 4rem;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: var(--text-base);
  line-height: 1.6;
  color: var(--text-primary);
  background: var(--bg-white);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* ============================================
   Typography
   ============================================ */

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.02em;
  color: var(--text-primary);
}

.text-display {
  font-size: var(--text-6xl);
  font-weight: 800;
  line-height: 1.05;
  letter-spacing: -0.03em;
}

.text-headline {
  font-size: var(--text-5xl);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

.text-title {
  font-size: var(--text-4xl);
  font-weight: 700;
  line-height: 1.15;
}

.text-subtitle {
  font-size: var(--text-2xl);
  font-weight: 600;
  line-height: 1.3;
}

.text-body-large {
  font-size: var(--text-lg);
  line-height: 1.6;
  color: var(--text-secondary);
}

.text-body {
  font-size: var(--text-base);
  line-height: 1.6;
  color: var(--text-secondary);
}

.text-small {
  font-size: var(--text-sm);
  line-height: 1.5;
  color: var(--text-muted);
}

.text-center { text-align: center; }

/* ============================================
   Layout Utilities
   ============================================ */

.container {
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 var(--space-6);
}

.container-narrow {
  max-width: var(--container-narrow);
  margin: 0 auto;
  padding: 0 var(--space-6);
}

.section {
  padding: var(--space-24) 0;
}

.section-sm {
  padding: var(--space-16) 0;
}

.section-lg {
  padding: var(--space-32) 0;
}

.grid {
  display: grid;
  gap: var(--space-6);
}

.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }
.grid-5 { grid-template-columns: repeat(5, 1fr); }
.grid-6 { grid-template-columns: repeat(6, 1fr); }

.flex {
  display: flex;
}

.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-center { justify-content: center; }
.justify-between { justify-content: space-between; }
.gap-2 { gap: var(--space-2); }
.gap-3 { gap: var(--space-3); }
.gap-4 { gap: var(--space-4); }
.gap-6 { gap: var(--space-6); }
.gap-8 { gap: var(--space-8); }
.gap-12 { gap: var(--space-12); }

/* ============================================
   Components
   ============================================ */

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  font-family: var(--font-heading);
  font-size: var(--text-base);
  font-weight: 600;
  border-radius: var(--radius-lg);
  transition: all var(--transition-base);
  white-space: nowrap;
}

.btn-primary {
  background: var(--brand-primary);
  color: white;
  box-shadow: var(--shadow-md);
}

.btn-primary:hover {
  background: var(--brand-primary-dark);
  transform: translateY(-1px);
  box-shadow: var(--shadow-lg);
}

.btn-secondary {
  background: var(--bg-elevated);
  color: var(--text-primary);
  border: 1.5px solid var(--border-light);
}

.btn-secondary:hover {
  border-color: var(--border-medium);
  background: var(--bg-surface);
}

.btn-accent {
  background: var(--brand-accent);
  color: white;
  box-shadow: var(--shadow-md);
}

.btn-accent:hover {
  filter: brightness(0.95);
  transform: translateY(-1px);
}

.btn-large {
  padding: var(--space-4) var(--space-8);
  font-size: var(--text-lg);
  border-radius: var(--radius-xl);
}

/* Cards */
.card {
  background: var(--bg-elevated);
  border-radius: var(--radius-xl);
  border: 1px solid var(--border-light);
  padding: var(--space-8);
  transition: all var(--transition-base);
}

.card:hover {
  box-shadow: var(--shadow-card);
  transform: translateY(-2px);
}

.card-feature {
  background: var(--bg-elevated);
  border-radius: var(--radius-xl);
  border: 1px solid var(--border-light);
  padding: var(--space-8);
}

/* Tags / Pills */
.tag {
  display: inline-flex;
  align-items: center;
  padding: var(--space-1) var(--space-3);
  font-size: var(--text-sm);
  font-weight: 600;
  border-radius: var(--radius-full);
  background: oklch(95% 0.05 265);
  color: var(--brand-primary);
}

.tag-accent {
  background: oklch(95% 0.08 145);
  color: oklch(40% 0.15 145);
}

/* ============================================
   Navigation
   ============================================ */

.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  height: var(--nav-height);
  background: oklch(99% 0.005 265 / 0.85);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-light);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}

.nav-logo {
  font-family: var(--font-heading);
  font-size: var(--text-xl);
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -0.03em;
}

.nav-logo span {
  color: var(--brand-primary);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: var(--space-8);
}

.nav-link {
  font-size: var(--text-sm);
  font-weight: 500;
  color: var(--text-secondary);
  transition: color var(--transition-fast);
  position: relative;
}

.nav-link:hover,
.nav-link.active {
  color: var(--text-primary);
}

.nav-link.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--brand-primary);
  border-radius: var(--radius-full);
}

.nav-cta {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

/* Mobile nav */
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 4px;
  padding: var(--space-2);
}

.nav-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--text-primary);
  transition: all var(--transition-base);
}

/* ============================================
   Hero Section
   ============================================ */

.hero {
  position: relative;
  padding: var(--space-24) 0 var(--space-16);
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, oklch(97% 0.02 265) 0%, oklch(96% 0.03 280) 50%, oklch(97% 0.02 265) 100%);
  z-index: -1;
}

.hero-bg::before {
  content: '';
  position: absolute;
  top: -20%;
  right: -10%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, oklch(70% 0.15 265 / 0.15) 0%, transparent 70%);
  border-radius: 50%;
}

.hero-bg::after {
  content: '';
  position: absolute;
  bottom: -10%;
  left: -5%;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, oklch(80% 0.12 145 / 0.1) 0%, transparent 70%);
  border-radius: 50%;
}

.hero-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-12);
  align-items: center;
}

.hero-content {
  max-width: 600px;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-4);
  background: oklch(95% 0.05 265);
  border-radius: var(--radius-full);
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--brand-primary);
  margin-bottom: var(--space-6);
}

.hero-title {
  font-size: var(--text-6xl);
  font-weight: 800;
  line-height: 1.05;
  letter-spacing: -0.03em;
  margin-bottom: var(--space-6);
}

.hero-title .highlight {
  color: var(--brand-primary);
}

.hero-subtitle {
  font-size: var(--text-lg);
  line-height: 1.7;
  color: var(--text-secondary);
  margin-bottom: var(--space-8);
}

.hero-cta {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  margin-bottom: var(--space-8);
}

.hero-tabs {
  display: inline-flex;
  background: var(--bg-surface);
  border-radius: var(--radius-full);
  padding: var(--space-1);
  border: 1px solid var(--border-light);
}

.hero-tab {
  padding: var(--space-2) var(--space-5);
  font-size: var(--text-sm);
  font-weight: 600;
  border-radius: var(--radius-full);
  color: var(--text-muted);
  transition: all var(--transition-base);
}

.hero-tab.active {
  background: var(--brand-primary);
  color: white;
  box-shadow: var(--shadow-sm);
}

.hero-tab:hover:not(.active) {
  color: var(--text-secondary);
}

.hero-visual {
  position: relative;
}

.hero-preview {
  background: var(--bg-elevated);
  border-radius: var(--radius-2xl);
  border: 1px solid var(--border-light);
  box-shadow: var(--shadow-xl);
  overflow: hidden;
  aspect-ratio: 4/3;
  display: flex;
  flex-direction: column;
}

.preview-header {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-4);
  background: var(--bg-surface);
  border-bottom: 1px solid var(--border-light);
}

.preview-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}

.preview-dot.red { background: oklch(70% 0.15 25); }
.preview-dot.yellow { background: oklch(80% 0.12 95); }
.preview-dot.green { background: oklch(70% 0.12 145); }

.preview-body {
  flex: 1;
  padding: var(--space-6);
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
}

.preview-card {
  background: var(--bg-surface);
  border-radius: var(--radius-lg);
  padding: var(--space-4);
  border: 1px solid var(--border-light);
}

.preview-card-header {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  margin-bottom: var(--space-3);
}

.preview-avatar {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-md);
  background: linear-gradient(135deg, var(--brand-primary), var(--brand-primary-light));
}

.preview-lines {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  flex: 1;
}

.preview-line {
  height: 8px;
  border-radius: var(--radius-full);
  background: var(--border-light);
}

.preview-line.short { width: 60%; }

.preview-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-3);
}

.preview-stat {
  text-align: center;
  padding: var(--space-3);
  background: var(--bg-white);
  border-radius: var(--radius-md);
  border: 1px solid var(--border-light);
}

.preview-stat-value {
  font-family: var(--font-heading);
  font-size: var(--text-lg);
  font-weight: 700;
  color: var(--brand-primary);
}

.preview-stat-label {
  font-size: var(--text-xs);
  color: var(--text-muted);
  margin-top: var(--space-1);
}

/* Student view variation */
.student-view .preview-avatar {
  background: linear-gradient(135deg, var(--brand-accent), oklch(75% 0.14 145));
}

.student-view .preview-stat-value {
  color: var(--brand-accent);
}

/* ============================================
   Stats Bar
   ============================================ */

.stats-bar {
  background: var(--text-primary);
  padding: var(--space-8) 0;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-8);
  text-align: center;
}

.stat-item {
  position: relative;
}

.stat-item:not(:last-child)::after {
  content: '';
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 1px;
  height: 40px;
  background: oklch(100% 0 0 / 0.15);
}

.stat-value {
  font-family: var(--font-heading);
  font-size: var(--text-4xl);
  font-weight: 800;
  color: white;
  letter-spacing: -0.02em;
}

.stat-value .accent {
  color: var(--brand-lime);
}

.stat-label {
  font-size: var(--text-sm);
  color: oklch(80% 0.02 265);
  margin-top: var(--space-2);
}

/* ============================================
   Section Headers
   ============================================ */

.section-header {
  text-align: center;
  max-width: 640px;
  margin: 0 auto var(--space-12);
}

.section-tag {
  display: inline-flex;
  padding: var(--space-1) var(--space-3);
  background: oklch(95% 0.05 265);
  color: var(--brand-primary);
  font-size: var(--text-sm);
  font-weight: 600;
  border-radius: var(--radius-full);
  margin-bottom: var(--space-4);
}

.section-title {
  font-size: var(--text-4xl);
  font-weight: 700;
  margin-bottom: var(--space-4);
}

.section-desc {
  font-size: var(--text-lg);
  color: var(--text-secondary);
  line-height: 1.6;
}

/* ============================================
   Products Grid
   ============================================ */

.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-6);
}

.product-card {
  background: var(--bg-elevated);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  transition: all var(--transition-base);
}

.product-card:hover {
  box-shadow: var(--shadow-card);
  transform: translateY(-4px);
  border-color: var(--border-medium);
}

.product-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-5);
  font-size: var(--text-xl);
}

.product-icon.blue { background: oklch(95% 0.05 265); }
.product-icon.green { background: oklch(95% 0.08 145); }
.product-icon.coral { background: oklch(95% 0.06 45); }
.product-icon.purple { background: oklch(95% 0.06 300); }

.product-card h3 {
  font-size: var(--text-xl);
  margin-bottom: var(--space-3);
}

.product-card p {
  font-size: var(--text-sm);
  color: var(--text-secondary);
  line-height: 1.6;
}

/* ============================================
   Why Choose Us (Tabs)
   ============================================ */

.why-tabs {
  display: flex;
  gap: var(--space-2);
  margin-bottom: var(--space-8);
  flex-wrap: wrap;
}

.why-tab {
  padding: var(--space-3) var(--space-5);
  font-family: var(--font-heading);
  font-size: var(--text-sm);
  font-weight: 600;
  border-radius: var(--radius-lg);
  color: var(--text-muted);
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  transition: all var(--transition-base);
  white-space: nowrap;
}

.why-tab:hover {
  color: var(--text-secondary);
}

.why-tab.active {
  background: var(--brand-primary);
  color: white;
  border-color: var(--brand-primary);
  box-shadow: var(--shadow-md);
}

.why-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-12);
  align-items: center;
}

.why-panel {
  display: none;
}

.why-panel.active {
  display: contents;
}

.why-features {
  display: flex;
  flex-direction: column;
  gap: var(--space-5);
}

.why-feature {
  display: flex;
  gap: var(--space-4);
  align-items: flex-start;
}

.why-feature-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-md);
  background: oklch(95% 0.05 265);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--brand-primary);
  font-size: var(--text-lg);
}

.why-feature h4 {
  font-size: var(--text-base);
  margin-bottom: var(--space-1);
}

.why-feature p {
  font-size: var(--text-sm);
  color: var(--text-secondary);
}

.why-visual {
  background: var(--bg-surface);
  border-radius: var(--radius-xl);
  border: 1px solid var(--border-light);
  padding: var(--space-8);
  min-height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.why-visual-inner {
  width: 100%;
  max-width: 400px;
}

/* ============================================
   Global Scale / AI Section
   ============================================ */

.feature-showcase {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-16);
  align-items: center;
}

.feature-showcase.reverse {
  direction: rtl;
}

.feature-showcase.reverse > * {
  direction: ltr;
}

.feature-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-5);
}

.feature-item {
  display: flex;
  gap: var(--space-4);
  align-items: flex-start;
}

.feature-check {
  width: 28px;
  height: 28px;
  border-radius: var(--radius-full);
  background: oklch(95% 0.08 145);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: oklch(40% 0.15 145);
  font-size: var(--text-sm);
  font-weight: 700;
}

.feature-item h4 {
  font-size: var(--text-base);
  margin-bottom: var(--space-1);
}

.feature-item p {
  font-size: var(--text-sm);
  color: var(--text-secondary);
}

.feature-visual {
  background: linear-gradient(135deg, oklch(97% 0.03 265), oklch(96% 0.02 280));
  border-radius: var(--radius-2xl);
  border: 1px solid var(--border-light);
  padding: var(--space-8);
  min-height: 360px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.feature-visual::before {
