  overflow: hidden;
}

.page-hero::before {
  content: '';
  position: absolute;
  top: -20%;
  right: -10%;
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, oklch(70% 0.12 265 / 0.1) 0%, transparent 70%);
  border-radius: 50%;
}

.page-hero-inner {
  text-align: center;
  max-width: 720px;
  margin: 0 auto;
  position: relative;
}

.page-hero h1 {
  font-size: var(--text-5xl);
  margin-bottom: var(--space-5);
}

.page-hero p {
  font-size: var(--text-xl);
  color: var(--text-secondary);
}

/* ============================================
   Steps
   ============================================ */

.steps {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-8);
}

.step {
  text-align: center;
  position: relative;
}

.step:not(:last-child)::after {
