  font-family: var(--font-heading);
  font-size: var(--text-2xl);
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-5);
  position: relative;
  z-index: 1;
}

.step h3 {
  font-size: var(--text-xl);
  margin-bottom: var(--space-3);
}

.step p {
  font-size: var(--text-sm);
  color: var(--text-secondary);
  line-height: 1.6;
}

/* ============================================
   Spotlight Cards
