    --text-6xl: 2.5rem;
    --text-5xl: 2rem;
    --text-4xl: 1.75rem;
    --text-3xl: 1.5rem;
  }

  .section {
    padding: var(--space-16) 0;
  }

  .nav-links {
    display: none;
    position: absolute;
